describe("doctests of sympy.integrals.deltafunctions", () => {
  it("change_mul(x*y*DiracDelta(x)*cos(x), x)", () => {
    const [x, y] = symbols('x y');
    const v1 = DiracDelta(x);
    expect(sympyMatches([v1, at(changeMul(mul(x, y, v1, fn('cos', [x], { evaluate: false })), x), 1)], '(DiracDelta(x), x*y*cos(x))')).toBe(true);
  });
  // a primitive result that no library call returned
  //   change_mul(x*y*DiracDelta(x**2 - 1)*cos(x), x)
  //   => (None, x*y*cos(x)*DiracDelta(x - 1)/2 + x*y*cos(x)*DiracDelta(x + 1)/2)
  it.todo("change_mul(x*y*DiracDelta(x**2 - 1)*cos(x), x)");
  // a primitive result that no library call returned
  //   change_mul(x*y*DiracDelta(cos(x))*cos(x), x)
  //   => (None, None)
  it.todo("change_mul(x*y*DiracDelta(cos(x))*cos(x), x)");
  it("deltaintegrate(x*sin(x)*cos(x)*DiracDelta(x - 1), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(deltaintegrate(mul(x, DiracDelta(add(Rational.of(-1n, 1n, { gcd: 1n }), x)), fn('cos', [x], { evaluate: false }), fn('sin', [x], { evaluate: false })), x))).toBe('sin(1)*cos(1)*Heaviside(x - 1)');
  });
  it("deltaintegrate(y**2*DiracDelta(x - z)*DiracDelta(y - z), y)", () => {
    const [y, x, z] = symbols('y x z');
    expect(sympyStr(deltaintegrate(mul(pow(y, Rational.of(2n, 1n, { gcd: 1n })), DiracDelta(add(x, mul(Rational.of(-1n, 1n, { gcd: 1n }), z))), DiracDelta(add(y, mul(Rational.of(-1n, 1n, { gcd: 1n }), z)))), y))).toBe('z**2*DiracDelta(x - z)*Heaviside(y - z)');
  });
});

